package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.NullValueProvider;
import com.fasterxml.jackson.databind.deser.impl.NullValueProviderImpl;
import com.fasterxml.jackson.databind.deser.impl.std.DelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.impl.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.impl.std.ValueInstantiatorImpl;
import com.fasterxml.jackson.databind.deser.std.ValueInstantiator;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class StringCollectionDeserializer_createContextual_TriageGen0Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        typeFactory = TypeFactory.defaultInstance();
        collectionType = typeFactory.constructCollectionType(Collection.class, String.class);
        contentType = collectionType.getContentType();

        when(ctxt.getConfig()).thenReturn(mock(MapperConfig.class));
    }

    @Test
    public void testCreateContextual_WithDelegateAndValueDeser() throws Exception {
        // Setup delegate instantiator
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        com.fasterxml.jackson.databind.deser.impl.std.AnnotatedWithParams delegateCreator = mock(com.fasterxml.jackson.databind.deser.impl.std.AnnotatedWithParams.class);

        when(instantiator.getDelegateCreator()).thenReturn(delegateCreator);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        // Setup value deserializer
        JsonDeserializer<?> valueDeser = mock(JsonDeserializer.class);

        // Mocking the behavior of the class under test (it's a partial mock/spy scenario for internal protected methods if needed, 
        // but here we use the real object and mock dependencies)
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, valueDeser, instantiator));

        // Mock findDeserializer (protected)
        JsonDeserializer<?> delegateDeser = mock(JsonDeserializer.class);
        doReturn(delegateDeser).when(deserializer).findDeserializer(eq(ctxt), eq(contentType), eq(property));

        // Mock handleSecondaryContextualization
        JsonDeserializer<?> contextualizedValueDeser = mock(JsonDeserializer.class);
        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(contextualizedValueDeser);

        // Mock findFormatFeature and findContentNullProvider via spy if necessary, 
        // but since they are likely protected/internal, we rely on default behavior or spy
        doReturn(false).when(deserializer).findFormatFeature(any(), any(), any(), any());
        doReturn(null).when(deserializer).findContentNullProvider(any(), any(), any());
        doReturn(false).when(deserializer).isDefaultDeserializer(any());

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        // Verify withResolved was called with correct parameters
        verify(deserializer).withResolved(eq(delegateDeser), eq(contextualizedValueDeser), isNull(), eq(false));
    }

    @Test
    public void testCreateContextual_NoDelegate_NoValueDeser_FindConverting() throws Exception {
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, null, null));

        // Mocking logic for when valueDeser is null
        JsonDeserializer<?> convertingDeser = mock(JsonDeserializer.class);
        doReturn(convertingDeser).when(deserializer).findConvertingContentDeserializer(eq(ctxt), eq(property), isNull());

        doReturn(false).when(deserializer).findFormatFeature(any(), any(), any(), any());
        doReturn(null).when(deserializer).findContentNullProvider(any(), any(), any());
        doReturn(false).when(deserializer).isDefaultDeserializer(any());

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deserializer).withResolved(isNull(), eq(convertingDeser), isNull(), eq(false));
    }

    @Test
    public void testCreateContextual_NoDelegate_NoValueDeser_FindContextual() throws Exception {
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, null, null));

        // Mocking logic for when valueDeser is null and converting fails
        doReturn(null).when(deserializer).findConvertingContentDeserializer(any(), any(), any());
        JsonDeserializer<?> contextualValueDeser = mock(JsonDeserializer.class);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(contextualValueDeser);

        doReturn(false).when(deserializer).findFormatFeature(any(), any(), any(), any());
        doReturn(null).when(deserializer).findContentNullProvider(any(), any(), any());
        doReturn(false).when(deserializer).isDefaultDeserializer(any());

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deserializer).withResolved(isNull(), eq(contextualValueDeser), isNull(), eq(false));
    }

    @Test
    public void testCreateContextual_IsDefaultDeserializer() throws Exception {
        JsonDeserializer<?> valueDeser = mock(JsonDeserializer.class);
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, valueDeser, null));

        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(valueDeser);

        doReturn(true).when(deserializer).isDefaultDeserializer(valueDeser);
        doReturn(false).when(deserializer).findFormatFeature(any(), any(), any(), any());
        doReturn(null).when(deserializer).findContentNullProvider(any(), any(), any());

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        // If isDefaultDeserializer is true, valueDeser becomes null in withResolved
        verify(deserializer).withResolved(isNull(), isNull(), isNull(), any());
    }

    @Test
    public void testCreateContextual_WithUnwrapSingleAndNuller() throws Exception {
        JsonDeserializer<?> valueDeser = mock(JsonDeserializer.class);
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, valueDeser, null));

        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(valueDeser);

        Boolean unwrapSingle = true;
        NullValueProvider nuller = NullValueProviderImpl.NO_OP;

        doReturn(unwrapSingle).when(deserializer).findFormatFeature(eq(ctxt), eq(property), eq(Collection.class), any());
        doReturn(nuller).when(deserializer).findContentNullProvider(eq(ctxt), eq(property), eq(valueDeser));
        doReturn(false).when(deserializer).isDefaultDeserializer(any());

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deserializer).withResolved(isNull(), eq(valueDeser), eq(nuller), eq(unwrapSingle));
    }

    @Test
    public void testCreateContextual_NoDelegateCreator() throws Exception {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.getDelegateCreator()).thenReturn(null);

        JsonDeserializer<?> valueDeser = mock(JsonDeserializer.class);
        StringCollectionDeserializer deserializer = spy(new StringCollectionDeserializer(collectionType, valueDeser, instantiator));

        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(valueDeser);
        doReturn(false).when(deserializer).findFormatFeature(any(), any(), any(), any());
        doReturn(null).when(deserializer).findContentNullProvider(any(), any(), any());
        doReturn(false).when(deserializer).isDefaultDeserializer(any());

        deserializer.createContextual(ctxt, property);

        verify(deserializer).withResolved(isNull(), any(), any(), any());
    }
}
